```javascript
import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
  PlaneGeometry,
  BoxGeometry,
  Group,
  Mesh,
  DirectionalLight,
  AmbientLight,
} from 'three/webgpu';
import { uv, vec3, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // ─── Backdrop ───────────────────────────────────────────────
  const backdropGeometry = new PlaneGeometry(7, 5.5);
  const gradientMaterial = new MeshBasicNodeMaterial();
  const u = uv();
  const gradient = mix(
    vec3(0x0b / 255, 0x0b / 255, 0x10 / 255),
    vec3(0x13 / 255, 0x13 / 255, 0x1a / 255),
    u.y
  );
  gradientMaterial.colorNode = gradient;
  const backdrop = new THREE.Mesh(backdropGeometry, gradientMaterial);
  backdrop.position.z = -1.5;
  group.add(backdrop);

  // ─── Lights ──────────────────────────────────────────────────
  const ambient = new THREE.AmbientLight(0x404060, 0.6);
  group.add(ambient);
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(5, 5, 5);
  group.add(keyLight);
  const rimLight = new THREE.DirectionalLight(0xe8ecf2, 0.8);
  rimLight.position.set(-5, 0, -5);
  group.add(rimLight);

  // ─── Extract text content from config ───────────────────────
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let heroText = '',
    subheadText = '',
    captionText = '';
  let heroFontSize = 0.62,
    subheadFontSize = 0.2,
    captionFontSize = 0.09;
  for (const item of items) {
    if (item.role === 'hero') {
      heroText = item.text;
      heroFontSize = item.typography?.fontSize ? item.typography.fontSize / 200 : 0.62;
    } else if (item.role === 'subhead') {
      subheadText = item.text;
      subheadFontSize = item.typography?.fontSize ? item.typography.fontSize / 200 : 0.2;
    } else if (item.role === 'caption') {
      captionText = item.text;
      captionFontSize = item.typography?.fontSize ? item.typography.fontSize / 200 : 0.09;
    }
  }

  // ─── Hero text ──────────────────────────────────────────────
  const heroGroup = ctx.fontAtlas.createText(heroText, {
    fontSize: heroFontSize,
    color: '#e8ecf2',
    align: 'center',
  });
  heroGroup.position.y = 0.4;
  group.add(heroGroup);

  // Apply per-word z offsets (front-to-back: 0.12, 0.0, -0.12)
  const glyphs = heroGroup.children.filter((c) => c.isMesh);
  const textChars = heroText.split('');
  const zOffsets = [0.12, 0.0, -0.12];
  let charIdx = 0;
  for (let i = 0; i < glyphs.length; i++) {
    if (textChars[charIdx] === ' ') {
      charIdx++; // skip space glyph
      continue;
    }
    const spacesBefore = textChars.slice(0, charIdx).filter((c) => c === ' ').length;
    const wordIdx = Math.min(spacesBefore, zOffsets.length - 1);
    glyphs[i].position.z = zOffsets[wordIdx];
    charIdx++;
  }

  // ─── Subhead text ───────────────────────────────────────────
  const subheadGroup = ctx.fontAtlas.createText(subheadText, {
    fontSize: subheadFontSize,
    color: '#e8ecf2',
    align: 'center',
  });
  subheadGroup.position.y = -0.65 + 0.2; // start below for animation
  subheadGroup.visible = true;
  subheadGroup.children.forEach((child) => {
    if (child.isMesh && child.material) {
      child.material.transparent = true;
      child.material.opacity = 0;
    }
  });
  group.add(subheadGroup);

  // ─── 3D Card behind subhead (center card depth) ──────────────
  const cardGeometry = new BoxGeometry(3.2, 0.8, 0.15);
  const cardMaterial = new MeshStandardNodeMaterial();
  cardMaterial.color = new THREE.Color('#16161d');
  cardMaterial.roughness = 0.5;
  cardMaterial.metalness = 0.05;
  const card = new THREE.Mesh(cardGeometry, cardMaterial);
  card.position.set(0, -0.65, -0.12);
  group.add(card);

  // ─── Caption text ───────────────────────────────────────────
  const captionGroup = ctx.fontAtlas.createText(captionText, {
    fontSize: captionFontSize,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.12 * captionFontSize,
  });
  captionGroup.position.y = 1.15;
  group.add(captionGroup);

  // ─── Accent underline ───────────────────────────────────────
  const underlineGeometry = new PlaneGeometry(2.8, 0.065);
  const underlineMaterial = new MeshStandardNodeMaterial();
  underlineMaterial.color = new THREE.Color('#ff2a38');
  underlineMaterial.emissive = new THREE.Color('#ff2a38');
  underlineMaterial.emissiveIntensity = 1.4;
  underlineMaterial.roughness = 0.3;
  underlineMaterial.metalness = 0.25;
  const underline = new THREE.Mesh(underlineGeometry, underlineMaterial);
  underline.position.set(0, -1.05, 0.08);
  underline.scale.x = 0;
  group.add(underline);

  // ─── Animation ──────────────────────────────────────────────
  // Apply kinetic-text primitive
  const kineticResult = ctx.primitives['kinetic-text'](heroGroup, {
    staggerMs: 60,
    riseUnits: 0.35,
  });

  // Count visible glyphs for timing
  const visibleGlyphCount = heroText.replace(/ /g, '').length;
  const kineticDuration = (visibleGlyphCount - 1) * 0.06 + 0.7; // seconds

  const tl = gsap.timeline({ paused: true });

  // Add kinetic timeline
  tl.add(kineticResult.timeline);

  // Weighted-settle on hero group (overshoot then settle)
  tl.to(heroGroup.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.3, ease: 'power4.out' }, `+=${kineticDuration}`);
  tl.to(heroGroup.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.6, ease: 'power4.out' }, '>');

  // Underline scale in
  const underlineStart = kineticDuration + 0.12;
  tl.to(underline.scale, {
    x: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  }, `+=${underlineStart}`);

  // Subhead fade up and settle
  const subheadStart = underlineStart;
  tl.to(subheadGroup.position, {
    y: -0.65,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  }, `+=${subheadStart}`);
  tl.to(subheadGroup.children, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  }, `+=${subheadStart}`);

  tl.play();

  // ─── Cleanup ────────────────────────────────────────────────
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    tl.kill();
    kineticResult.cleanup();
    backdropGeometry.dispose();
    gradientMaterial.dispose();
    cardGeometry.dispose();
    cardMaterial.dispose();
    underlineGeometry.dispose();
    underlineMaterial.dispose();
    group.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });
  };

  return group;
}
